GimCorpus.put(434,0,[[1,10,"כמעשה תמיד וכו' עד שלא יחקו את המינין. א\"א אני שמעתי שמא יצטער בכפייתו ויפרכס עד שיטיל מום באחד מאיבריו ובגמ' דתמיד מצאנו דפליגי רב הונא ורב חסדא חד אמר משום בזיון קדשים וחד אמר משום חקי המינין ואפשר שהטעם הראשון הוא בזיון קדשים אבל חקי המינין לא ידעתי מהו:",1,0],[2,7,"כשמסדר עצי המערכה וכו'. א\"א זה כתב במקום וחזיתה מזרחה ולא כיון יפה אלא לומר שלא יהיו הגזרים הולכין צפון ודרום אלא מזרח ומערב והיינו ראשי הגזרים הפנימים נוגעין בתפוח ולא בא להוסיף אלא שיהיו נוגעים בתפוח שלא ירחיקו מהלך רגלי הכהנים שהיה אמה שלא יקרעו ולא ישרפו בגדיהם. ומ\"ש שהדשן שהיה באמצע המזבח הוא הנקרא תפוח מראה בדעתו שלא היה שם גבשושית אחרת אלא על הדשן המכונס שם וטעה טעות גדולה שהרי שנינו החלו מעלים באפר ע\"ג התפוח ומאחר שכהן מוציא בכל יום כל האפר מהיכן היה שם התפוח. וכן אמרו פעמים שעליו כשלש מאות כור והיה לו לומר פעמים שיש בו כשלש מאות אלא שהיה שם טבלא מרובעת גבוהה אמה והיא כ\"ב על כ\"ב אמות ואותה אמה היא השלמת עשר אמות לגובה המזבח והיא נקראת תפוח על שם שהיתה גבוהה על כל סביביה ואפשר שהיתה אותה הטבלא קצוצת קרנות כעין עגולה כדי להרויח מקום המערכה וכל דבר שהוא גבוה ועגול נקרא תפוח כדאמרינן בנדה מקום יש באותו מקום כעין תפוח ובע\"ז אע\"פ שנטל בידו ונתן לתוך התפוח:",1,0],[2,15,"ושמו שיניחנו בנחת. א\"א זה לא נאמר אלא על תרומת הדשן ואין מעילה אלא בתרומת הדשן:",1,0],[3,5,"וכיצד חותה וכו' עד שנתאכלו במערכה. א\"א אין זה בנוסחא המדויקת לענין קטרת אלא לענין תרומת הדשן:",1,0],[3,13,"נר מערבי. א\"א נראה מדבריו שהוא עכוב לנר מערבי שלא להדליקו אלא ממזבח העולה. ואני אומר כשאמרו מצאו שכבה מדשנו ומדליקין ממזבח העולה מפני שלא היה במנורה נר דולק שכבר הטיב את כולה והתורה אמרה אש תמיד תוקד על המזבח אש שיש לו תמיד לא יהא אלא ממזבח העולה שלא יביא ממזבח הפנימי ולא מבית הכירים אבל בזמן שיש נר דולק במנורה ומצא המערבי כבה מדליקו מן הדולק ומשנה שלימה היא נכנס ומצא שני נרות מזרחיים דולקים מדשן את השאר ומניח אלו דולקים במקומן שממנו מדליק המנורה בין הערבים מצאן שכבו מדשנן ומדליקן מן הדולקין ואח\"כ מדשן את השאר אלמא כל היכא דאפשר מיניה וביה טפי עדיף:",1,0],[4,12,"וכן אם חל יו\"ט וכו' עד ודבר זה תקנה. א\"א איני יודע מה שאמר כדי שיתאחרו והלא על כרחם מתאחרים ולפיכך הם חולקים. ומ\"ש ואם נתאחר אחד מבעלי משמר וכו' הכל הבל:",1,0],[4,13,"חל יום אחד וכו' עד וזה הנכנס נוטל שתים. א\"א כל מה שכתב בכאן הבל ורעיון רוח שהמשמר שזמנו קבוע הם שני משמרות של אותה שבת והם נוטלין י' חלות והמשמר שהוא רחוק מביתו ולא יגיע לביתו ביום אחד מתעכב שם ונוטל שתי חלות:",1,0],[8,2,"שתי הלחם. א\"א הלכה זו בהפך:",1,0],[8,15,"שתי הלחם וכו'. א\"א הלכה זו בהפך:",1,0],[8,15,"ואם הונפו. א\"א ספק הוא בגמרא:",2,0],[8,19,"איל כו' ואם נשחטו כו'. א\"א לא ידעתי שחיטה זו בכאן מה היא והיה לו לומר אבל הן עצמן דתורת כהנים ומעכבין זה את זה מ\"ט הויה כתיב בהו:",1,0]]);
